package br.com.eventmenu.go.data
import br.com.eventmenu.go.security.SecureSessionStore
import org.json.JSONArray
class ReceiptRepository(baseUrl:String,deviceId:String,private val sessionStore:SecureSessionStore){private val api=ApiClient(baseUrl,deviceId)
 suspend fun order(orderId:Int):OrderReceipt{val r=api.getReceipt("order",requireToken(),mapOf("order_id" to orderId.toString())).getJSONObject("receipt");val ij=r.optJSONArray("items")?:JSONArray();val pj=r.optJSONArray("payments")?:JSONArray();val items=buildList{for(i in 0 until ij.length()){val x=ij.getJSONObject(i);add(ReceiptItem(x.optString("name_snapshot"),x.optDouble("quantity",1.0),x.optInt("unit_price_cents"),x.optInt("total_cents")))}};val payments=buildList{for(i in 0 until pj.length()){val x=pj.getJSONObject(i);add(ReceiptPayment(x.optInt("id"),x.optString("provider"),x.optString("method"),x.optInt("amount_cents"),x.optString("status"),x.optString("verified_at")))}};val p=r.optJSONObject("presentation");val q=p?.optJSONObject("qr");val s=p?.optJSONObject("sections");val a=p?.optJSONObject("advertisement");val presentation=ReceiptPresentation(p?.optInt("schema_version",1)?:1,p?.optString("paper_width","80")?:"80",p?.optString("title","COMPROVANTE NÃO FISCAL")?:"COMPROVANTE NÃO FISCAL",p?.optString("subtitle","Documento operacional EventMenu")?:"Documento operacional EventMenu",p?.optString("footer","Obrigado pela preferência!")?:"Obrigado pela preferência!",ReceiptQr(q?.optBoolean("enabled",false)?:false,q?.optString("payload","")?:"",q?.optString("label","QR DO PEDIDO")?:"QR DO PEDIDO",q?.optString("help","")?:""),ReceiptSections(s?.optBoolean("business",true)?:true,s?.optBoolean("customer",true)?:true,s?.optBoolean("items",true)?:true,s?.optBoolean("payments",true)?:true,s?.optBoolean("operator",true)?:true,s?.optBoolean("customer_phone",true)?:true,s?.optBoolean("event",true)?:true),ReceiptAdvertisement(a?.optBoolean("enabled",false)?:false,a?.optString("label","PUBLICIDADE")?:"PUBLICIDADE",a?.optString("headline","")?:"",a?.optString("body","")?:"",a?.optString("image_url","")?:"",a?.optString("target_url","")?:"",a?.optString("campaign","")?:""));return OrderReceipt(r.optString("receipt_number"),r.optString("tenant_name"),r.optInt("order_id"),r.optString("channel"),r.optString("status"),r.optString("payment_status"),r.optString("customer_name"),r.optString("customer_phone"),r.optString("table_name"),r.optInt("subtotal_cents"),r.optInt("discount_cents"),r.optInt("delivery_fee_cents"),r.optInt("total_cents"),r.optInt("paid_cents"),r.optString("created_at"),items,payments,presentation)}
 suspend fun group(groupId:Int):GroupReceipt{val r=api.getReceipt("group",requireToken(),mapOf("group_id" to groupId.toString())).getJSONObject("receipt");val aj=r.optJSONArray("allocations")?:JSONArray();val ij=r.optJSONArray("items")?:JSONArray();val allocations=buildList{for(i in 0 until aj.length()){val x=aj.getJSONObject(i);add(GroupReceiptAllocation(x.optInt("order_id"),x.optInt("payment_id"),x.optInt("amount_cents"),x.optString("payment_status"),x.optString("verified_at")))}};val items=buildList{for(i in 0 until ij.length()){val x=ij.getJSONObject(i);add(GroupReceiptItem(x.optInt("order_item_id"),x.optInt("order_id"),x.optString("name_snapshot"),x.optDouble("quantity",1.0),x.optInt("amount_cents")))}};return GroupReceipt(r.optString("receipt_number"),r.optString("tenant_name"),r.optInt("group_id"),if(r.isNull("tab_id"))null else r.optInt("tab_id"),r.optString("table_name"),r.optString("tab_label"),r.optString("operator_name"),r.optString("split_type"),r.optString("method"),r.optString("provider"),r.optString("status"),r.optInt("amount_cents"),r.optInt("confirmed_cents"),r.optString("provider_payment_id"),r.optString("verified_at"),r.optString("created_at"),allocations,items)}
 fun shareText(r:OrderReceipt)=buildString{val p=r.presentation;val s=p.sections;if(s.business)appendLine(r.tenantName);appendLine(p.title);appendLine("${p.subtitle} · ${r.receiptNumber}");appendLine("Pedido #${r.orderId} · ${channelLabel(r.channel)}");appendLine("Data: ${r.createdAt}");if(s.customer&&r.customerName.isNotBlank())appendLine("Cliente: ${r.customerName}");if(s.customer&&s.customerPhone&&r.customerPhone.isNotBlank())appendLine("Telefone: ${r.customerPhone}");if(r.tableName.isNotBlank())appendLine("Mesa: ${r.tableName}");if(s.items){appendLine("--------------------------------");r.items.forEach{val q=if(it.quantity%1.0==0.0)it.quantity.toInt().toString()else it.quantity.toString();appendLine("${q}x ${it.name}  ${money(it.totalCents)}")};appendLine("--------------------------------");appendLine("Subtotal: ${money(r.subtotalCents)}");if(r.discountCents>0)appendLine("Desconto: -${money(r.discountCents)}");if(r.deliveryFeeCents>0)appendLine("Entrega: ${money(r.deliveryFeeCents)}");appendLine("TOTAL: ${money(r.totalCents)}")};if(s.payments){appendLine("--------------------------------");appendLine("Pagamentos");r.payments.forEach{appendLine("${methodLabel(it.method,it.provider)} · ${money(it.amountCents)} · ${statusLabel(it.status)}")}};if(p.qr.enabled&&p.qr.payload.isNotBlank()){appendLine("--------------------------------");appendLine(p.qr.label);appendLine("[[EVENTMENU_QR:${p.qr.payload}]]");if(p.qr.help.isNotBlank())appendLine(p.qr.help)};if(p.advertisement.enabled){appendLine("--------------------------------");appendLine(p.advertisement.label);if(p.advertisement.headline.isNotBlank())appendLine(p.advertisement.headline);if(p.advertisement.body.isNotBlank())appendLine(p.advertisement.body);if(p.advertisement.targetUrl.isNotBlank())appendLine("[[EVENTMENU_QR:${p.advertisement.targetUrl}]]")};appendLine("--------------------------------");appendLine(p.footer)}
 fun shareText(r:GroupReceipt)=buildString{appendLine(r.tenantName);appendLine("EVENTMENU GO · COMPROVANTE DA DIVISAO");appendLine(r.receiptNumber);if(r.tableName.isNotBlank())appendLine("Mesa: ${r.tableName}");r.tabId?.let{appendLine("Comanda #$it${if(r.tabLabel.isNotBlank())" · ${r.tabLabel}" else ""}")};appendLine("Divisao: ${splitLabel(r.splitType)}");appendLine("Forma: ${methodLabel(r.method,r.provider)}");appendLine("Data: ${r.verifiedAt.ifBlank{r.createdAt}}");appendLine("--------------------------------");r.items.forEach{appendLine("${it.quantity}x ${it.name} · Pedido #${it.orderId} · ${money(it.amountCents)}")};appendLine("VALOR DESTA PARTE: ${money(r.amountCents)}");appendLine("Confirmado: ${money(r.confirmedCents)}")}
 private fun requireToken()=sessionStore.token()?:throw ApiException("Sessão não encontrada.",401);private fun money(c:Int)="R$ %.2f".format(c/100.0).replace('.',',');private fun channelLabel(c:String)=when(c){"counter"->"Balcão";"pickup"->"Retirada";"table"->"Mesa";"delivery"->"Delivery";"event"->"Evento";"bar"->"Bar";else->c};private fun methodLabel(m:String,p:String)=when(m.lowercase()){"cash"->"Dinheiro";"pix"->"PIX";"nfc"->"Cartão NFC";"card"->"Cartão";else->p};private fun splitLabel(v:String)=when(v){"value"->"Por valor";"percentage"->"Por percentual";"person"->"Por pessoa";"product"->"Por produto";else->v};private fun statusLabel(s:String)=when(s){"paid"->"Confirmado";"refunded"->"Estornado";"partially_refunded"->"Estorno parcial";"duplicate_paid"->"Duplicado";"attention"->"Atenção";else->s}}
